PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS programs (id TEXT PRIMARY KEY, department_id TEXT NOT NULL REFERENCES departments(id), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS academic_sessions (id TEXT PRIMARY KEY, label TEXT NOT NULL UNIQUE, is_current INTEGER NOT NULL DEFAULT 0 CHECK(is_current IN (0,1)));
CREATE TABLE IF NOT EXISTS semesters (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), name TEXT NOT NULL, is_current INTEGER NOT NULL DEFAULT 0 CHECK(is_current IN (0,1)), UNIQUE(session_id,name));
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, full_name TEXT NOT NULL, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','department_admin','lecturer','student')), department_id TEXT REFERENCES departments(id), is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS students (user_id TEXT PRIMARY KEY REFERENCES users(id), matric_no TEXT NOT NULL UNIQUE, program_id TEXT NOT NULL REFERENCES programs(id), level INTEGER NOT NULL CHECK(level IN (100,200,300,400,500,600)));
CREATE TABLE IF NOT EXISTS lecturers (user_id TEXT PRIMARY KEY REFERENCES users(id), staff_no TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS courses (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, title TEXT NOT NULL, units INTEGER NOT NULL CHECK(units BETWEEN 1 AND 10), department_id TEXT NOT NULL REFERENCES departments(id), level INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS course_offerings (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), semester_id TEXT NOT NULL REFERENCES semesters(id), lecturer_id TEXT REFERENCES lecturers(user_id), capacity INTEGER NOT NULL DEFAULT 200, UNIQUE(course_id,semester_id));
CREATE TABLE IF NOT EXISTS course_registrations (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES students(user_id), offering_id TEXT NOT NULL REFERENCES course_offerings(id), registered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(student_id,offering_id));
CREATE TABLE IF NOT EXISTS grading_scales (grade TEXT PRIMARY KEY, min_score INTEGER NOT NULL, max_score INTEGER NOT NULL, grade_point REAL NOT NULL);
CREATE TABLE IF NOT EXISTS result_submissions (id TEXT PRIMARY KEY, offering_id TEXT NOT NULL REFERENCES course_offerings(id), lecturer_id TEXT NOT NULL REFERENCES lecturers(user_id), status TEXT NOT NULL CHECK(status IN ('draft','submitted','approved','rejected','reopened')), feedback TEXT, submitted_at TEXT, reviewed_by TEXT REFERENCES users(id), reviewed_at TEXT, UNIQUE(offering_id));
CREATE TABLE IF NOT EXISTS result_entries (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES result_submissions(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES students(user_id), ca_score REAL NOT NULL CHECK(ca_score BETWEEN 0 AND 30), exam_score REAL NOT NULL CHECK(exam_score BETWEEN 0 AND 70), total_score REAL NOT NULL CHECK(total_score BETWEEN 0 AND 100), grade TEXT NOT NULL REFERENCES grading_scales(grade), grade_point REAL NOT NULL, UNIQUE(submission_id,student_id));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_reg_student ON course_registrations(student_id);
CREATE INDEX IF NOT EXISTS idx_offering_semester ON course_offerings(semester_id);
CREATE INDEX IF NOT EXISTS idx_submission_status ON result_submissions(status);
